PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (SUM(?o * ?p / 100) AS ?total) WHERE {
  { SELECT ?c (SUM(?oil) AS ?o) WHERE {
      ?wp a energia:WellProduction ; energia:inConcession ?c ; energia:oil ?oil .
    } GROUP BY ?c }
  { SELECT ?c (SUM(?pct) AS ?p) WHERE {
      ?s a energia:Stake ; energia:inConcession ?c ; energia:partner ?e ; energia:percent ?pct .
      FILTER EXISTS { ?e energia:name ?n . FILTER(UCASE(STR(?n)) = "YPF" || STRSTARTS(UCASE(STR(?n)), "YPF S.A")) }
    } GROUP BY ?c }
}
